command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1"
$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC cleanup"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $main){throw "UNC work branch is not accepted main"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "UNC work branch delete failed"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "UNC cleanup prune failed"}
if(& git branch -r --list ("origin/"+$branch)){throw "UNC work branch still present after prune"}
Write-Host "UNC_COPY_MOVE_WORK_BRANCH_CLEANUP=PASS"
Write-Host "UNC_COPY_MOVE_ACCEPTED_MAIN=$main"
